const roster=window.FANGORN_ROSTER, story=window.FANGORN_STORY, nando=window.FANGORN_NANDO, v2content=window.RPG_MASTER_V2_CONTENT||{}, codexContent=window.RPG_MASTER_CAMPAIGN_CODEX||{visualEntries:[],creatures:[]};
const portraits={elenya:'assets/portraits/elenya-hd.png',calion:'assets/portraits/calion-hd.png',nando:'assets/portraits/nando-hd.png',anao:'assets/portraits/anao-caolho-hd.png'};
const sprites={elenya:'assets/sprites/elenya-sprite-v3.png',calion:'assets/sprites/calion-sprite-v2.png',nando:'assets/sprites/nando-sprite-v2.png',anao:'assets/sprites/anao-sprite-v2.png'};
const labels={elenya:'Humana · Ladina',calion:'Elfo · Feiticeiro',nando:'Meio-Elfo · Bardo — Nível 1',anao:'Anão · Bárbaro Rúnico — Nível 4'};
const cats=['Todas','Personagens','NPCs','Criaturas','Mapas','Cenários','Itens','Outros'];
let db, state, gallery=[], timer, activeGallery='Todas', dwarfTimer, dwarfActionTimer, dwarfSoundTimer, diceTimer, dice3d, dice3dBoot, diceRolling=false;
const dwarfFrames={idle:Array.from({length:8},(_,i)=>`assets/sprites/anao-controlled-v1/idle-${i}.png`),action:Array.from({length:16},(_,i)=>`assets/sprites/anao-controlled-v1/action-${i}.png`)};
const characterClicks={anao:[]};
function defaultChars(){return Object.fromEntries(roster.characters.map(c=>{let s=c.source,id=c.id,details=s.details||{}, attrs=s.attributes||s.sourceAttributes?.slice(1).map(a=>({name:a[0],value:a[1],modifier:a[2],save:a[3]}))||[];let skills=s.tables?.pericias?.slice(1)||s.sourceSkills?.slice(1)||[];let powers=s.tables?.poderes?.slice(1)||[];let inv=s.tables?.inventario?.slice(1)||[];let background=s.tables?.background?.slice(1).map(x=>x[1]).filter(Boolean)||s.sourceParagraphs||[];if(id==='nando'){let f=nando.sheets.Ficha.rows, data=Object.fromEntries(f.filter(r=>r[0]).map(r=>[r[0],r[1]]));attrs=f.slice(21).map(r=>({name:r[0],value:r[1],modifier:r[2],allocated:r[3]}));skills=nando.sheets.Perícias.rows.slice(1);powers=nando.sheets.Magias.rows.slice(1);inv=nando.sheets.Equipamentos.rows.slice(1).map(x=>[x[0],'']);background=[nando.sheets.Histórico.rows[1][0]];details={Nome:'Nando Serenata',Raça:data.Raça,'Classe e Nível':data['Classe e Nível'],CA:data.CA,PV:data.PV,Iniciativa:data.Iniciativa,Deslocamento:data.Deslocamento,'Bônus de Proficiência':data['Bônus de Proficiência'],Renome:data.Renome,Inspiracao:data.Inspiracao,Antecedente:data.Antecedente,Idiomas:data.Idiomas};}
return [id,{id,name:c.displayName,rawSourceName:s.sourceName||c.displayName,sourceFile:s.sourceFile,info:{race:details.Raça||s.headerText?.match(/Raça:\s*([^\n]+)/)?.[1]||'—',classLevel:details['Classe e Nível']||s.sourceClass||'—',background:details.Antecedente||'—',languages:details.Idiomas||'—',renown:details.Renome||'—'},combat:{hpCurrent:String(details.PV||s.sourceParagraphs?.find(x=>x.includes('PV:'))?.match(/PV\):\s*(\d+)/)?.[1]||'—'),hpMax:String(details.PV||s.sourceParagraphs?.find(x=>x.includes('PV:'))?.match(/PV\):\s*(\d+)/)?.[1]||'—'),ac:String(details.CA||s.sourceParagraphs?.find(x=>x.includes('CA:'))?.match(/CA\):\s*([^\n]+)/)?.[1]||'—'),initiative:String(details.Iniciativa||s.sourceParagraphs?.find(x=>x.includes('Iniciativa:'))?.split(':')[1]?.trim()||'—'),movement:String(details.Deslocamento||s.sourceParagraphs?.find(x=>x.includes('Deslocamento:'))?.split(':')[1]?.trim()||'—'),proficiency:String(details['Bônus de Proficiência']||'—'),inspiration:String(details.Inspiracao||'—')},attributes:attrs.map(a=>({name:a.name||a[0],value:String(a.value??a[1]??''),modifier:String(a.modifier??a[2]??''),save:String(a.save??a[3]??''),allocated:String(a.allocated??'')})),skills:skills.map(x=>Array.isArray(x)?x:[x]),powers:powers.map(x=>Array.isArray(x)?x:[x]),inventory:inv.map(x=>Array.isArray(x)?x:[x]),background,notes:[],portrait:portraits[id],sourceDiscrepancies:id==='nando'?['Nome da planilha: Nando Serenato; navegação da aventura: Nando Serenata.','Histórico original identifica Elarion Dúnhir.','Aventura cita alaúde; inventário da planilha traz Harpa prateada de Rivendell.','Aventura indica nível 4; ficha-fonte: Bardo — Nível 1.']:[]}];}));}
function baseAdventures(){return [
 {id:'a1',number:1,title:'Abertura da Campanha',category:'Abertura da campanha',source:'Aventura 1.docx',status:'Planejada',description:'A abertura da campanha e a primeira sessão.'},
 {id:'a2',number:2,title:'Crônica de Origem – As Sombras de Tharbad',category:'Roteiro de origem',source:'aventura 2 - Crônica de Origem – “As Sombras de Tharbad”.docx',status:'Planejada',description:'Roteiro de origem, incluindo apontamentos históricos do mestre.'},
 {id:'a3',number:3,title:'Crônica Invernal – O Azul que Caminha na Neve',category:'Especial invernal',source:'aventura 3 - Crônica Invernal – O Azul que Caminha na Neve.docx',status:'Planejada',description:'Especial invernal e continuação O Silêncio sob o Gelo.'},
 {id:'a4',number:4,title:'Crônica dos Três Destinos Parte I – A Marca e a Luz',category:'Parte I da crônica',source:'aventura 4 - Crônica dos Três - Destinos Parte I_ A Marca e a Luz.docx',status:'Planejada',description:'A primeira parte da Crônica dos Três Destinos.'},
 {id:'a5',number:5,title:'Parte II – A Floresta que Lembra',category:'Parte II da crônica',source:'Aventura 5.docx',status:'Em andamento',description:'História 5 já publicada e preservada no leitor aprovado.',protected:true}
]}
function fresh(){return {schemaVersion:3,app:{view:'home',char:'anao',tab:'Visão Geral',sound:false,lastSection:0,diceType:20,diceBonus:0},characters:defaultChars(),diceHistory:[],v2:{activeAdventure:'a5',adventures:baseAdventures(),adventureState:{},lofi:[],importedDocuments:[],importedMaps:[],visualLibrary:[],creatures:[],ui:{}},updatedAt:new Date().toISOString()}}
function ensureV2(){state.schemaVersion=3;state.app=state.app||{};state.v2=state.v2||{};state.v2.activeAdventure??='a5';state.v2.adventures??=baseAdventures();state.v2.adventureState??={};state.v2.lofi??=[];state.v2.importedDocuments??=[];state.v2.importedMaps??=[];state.v2.visualLibrary??=[];state.v2.creatures??=[];state.v2.ui??={};state.v2.adventures.forEach(a=>{state.v2.adventureState[a.id]??={notes:'',favorites:[],lastSection:0,lastOpened:null}})}
function openDB(){return new Promise(resolve=>{try{let r=indexedDB.open('fangorn-rpg-v1',1);r.onupgradeneeded=()=>{r.result.createObjectStore('state');r.result.createObjectStore('gallery',{keyPath:'id'})};r.onsuccess=()=>{db=r.result;resolve()};r.onerror=()=>resolve()}catch(_){resolve()}})}
function getStore(name,mode='readonly'){return db?.transaction(name,mode).objectStore(name)}
function loadDB(){return new Promise(resolve=>{if(!db)return resolve();let r=getStore('state').get('main');r.onsuccess=()=>{if(r.result)state=r.result;let g=getStore('gallery').getAll();g.onsuccess=()=>{gallery=g.result||[];resolve()};g.onerror=resolve};r.onerror=resolve})}
function persist(){state.updatedAt=new Date().toISOString();clearTimeout(timer);$('#save-state').textContent='Salvando…';timer=setTimeout(()=>{try{localStorage.setItem('fangorn-rpg-state',JSON.stringify(state))}catch(_){} if(db){let r=getStore('state','readwrite').put(state,'main');r.onsuccess=()=>saved();r.onerror=saved()}else saved()},250)}
function saved(){$('#save-state').textContent='Salvo localmente';}
function saveGallery(item){return new Promise((res,rej)=>{if(!db)return rej(Error('IndexedDB indisponível'));let r=getStore('gallery','readwrite').put(item);r.onsuccess=res;r.onerror=()=>rej(r.error)})}
function render(){clearInterval(dwarfTimer);clearInterval(dwarfActionTimer);clearTimeout(dwarfSoundTimer);let v=state.app.view;let content=v==='home'?home():v==='story'?storyView():v==='players'?players():v==='character'?character():v==='dice'?diceView():v==='gallery'?galleryView():v==='creatures'?creaturesView():v==='adventures'?adventuresView():v==='v2reader'?v2ReaderView():v==='source-reader'?sourceReaderView():v==='lofi'?lofiView():v==='maps'?mapsView():v==='rules'?rulesView():v==='documents'?documentsView():settings();$('#app').innerHTML=`<div class="shell"><header class="topbar"><span class="brand-mini">Crônica dos Três Destinos</span>${nav()}</header><section class="view">${content}</section><footer class="statusbar"><span>Fangorn / História 5 · funcionamento local e offline</span><span id="save-state">Salvo localmente</span></footer></div>`;bind();bindDice();startDwarfFrames();if(v==='dice')bootDice3d()}
function dwarfActor(){return `<img class="frame-actor frame-actor-anao" data-dwarf-frame src="${dwarfFrames.idle[0]}" role="img" alt="Animação do Anão Caolho de Hirnath">`}
function dwarfActors(){return [...document.querySelectorAll('[data-dwarf-frame]')]}
function preloadDwarfFrames(){[...dwarfFrames.idle,...dwarfFrames.action].forEach(src=>{let image=new Image();image.src=src})}
function startDwarfFrames(){let actors=dwarfActors();if(!actors.length)return;let i=0;actors.forEach(a=>a.src=dwarfFrames.idle[i]);dwarfTimer=setInterval(()=>{i=(i+1)%dwarfFrames.idle.length;actors.forEach(a=>a.src=dwarfFrames.idle[i])},125)}
function playDwarfAction(actor){if(!actor)return;clearInterval(dwarfTimer);clearInterval(dwarfActionTimer);clearTimeout(dwarfSoundTimer);let actors=dwarfActors(),i=0;actors.forEach(a=>a.src=dwarfFrames.action[0]);dwarfSoundTimer=setTimeout(()=>playCharacterSound('anao'),1000);dwarfActionTimer=setInterval(()=>{i++;if(i>=dwarfFrames.action.length){clearInterval(dwarfActionTimer);actors.forEach(a=>a.src=dwarfFrames.idle[0]);startDwarfFrames();return}actors.forEach(a=>a.src=dwarfFrames.action[i])},125)}
function nav(){let v=state.app.view,biblioteca=['maps','rules','documents','gallery','creatures'].includes(v);return `<button class="nav-btn ${v==='story'?'active':''}" data-view="story">▣ História</button><button class="nav-btn ${v==='adventures'||v==='v2reader'?'active':''}" data-view="adventures">⚔ Aventuras</button><div class="players-menu"><button class="nav-btn ${v==='players'||v==='character'?'active':''}" id="players-menu" aria-expanded="false">♟ Jogadores ▾</button><div class="dropdown" id="dropdown">${Object.values(state.characters).map(c=>`<button class="drop-item" data-char="${c.id}">${E(c.name)}</button>`).join('')}<button class="drop-item" data-view="players">Ver todos</button></div></div><button class="nav-btn ${v==='dice'?'active':''}" data-view="dice">⚄ Dados</button><button class="nav-btn ${v==='lofi'?'active':''}" data-view="lofi">♫ LOFI</button><div class="players-menu"><button class="nav-btn ${biblioteca?'active':''}" id="library-menu" aria-expanded="false">▧ Biblioteca ▾</button><div class="dropdown" id="library-dropdown"><button class="drop-item" data-view="gallery">▧ Imagens</button><button class="drop-item" data-view="creatures">♞ Criaturas</button><button class="drop-item" data-view="maps">⌖ Mapas</button><button class="drop-item" data-view="rules">⚖ Regras</button><button class="drop-item" data-view="documents">✉ Documentos</button></div></div><button class="nav-btn ${v==='settings'?'active':''}" data-view="settings">⚙ Configurações</button>`}
function home(){return `<div class="home"><div class="home-hero"><div class="cover-copy"><h1>Crônica dos<br>Três Destinos</h1><h2>Parte II: A Floresta que Lembra</h2><button class="metal-btn" data-view="story">▣ Continuar História</button></div><aside class="session-card"><h3>Sessão atual</h3><b>Parte II: A Floresta que Lembra</b><br>Local: Floresta de Fangorn<br>Nível inicial: 4<br>Nível ao final: 5<br>Duração estimada: 4h30 a 5h30<br><br><em>“Existe algo mais antigo naquela floresta.”</em></aside></div></div>`}
function storyView(){let h=story.headings||[];return `<div class="story-layout"><aside class="story-side panel"><h2>Navegação rápida</h2>${h.map(x=>`<button class="story-link l${Math.min(x.level,3)}" data-jump="b${x.blockIndex}">${E(x.label)}</button>`).join('')}</aside><article class="story-reader panel"><header class="reader-head"><input class="reader-search" id="reader-search" placeholder="Buscar na aventura…"><h1>${E(story.title||'História')}</h1></header><div class="story-scroll" id="story-scroll"><div class="parchment-page">${story.blocks.map((b,i)=>block(b,i)).join('')}</div></div></article></div>`}
function block(b,i){let text=E(b.text||'');if(b.type==='table'){let rows=b.rows||[];return `<div class="story-block" id="b${i}"><table class="story-table">${rows.map(r=>`<tr>${(Array.isArray(r)?r:[r]).map(c=>`<td>${E(c)}</td>`).join('')}</tr>`).join('')}</table></div>`}let tag=/Heading 1/i.test(b.style)?'h1':/Heading 2/i.test(b.style)?'h2':/Heading 3/i.test(b.style)?'h3':'p';let rich=(b.runs||[]).map(x=>`${x.bold?'<strong>':''}${x.italic?'<em>':''}${E(x.text)}${x.italic?'</em>':''}${x.bold?'</strong>':''}`).join('')||text;return `<div class="story-block" id="b${i}"><${tag}>${rich}</${tag}></div>`}
function v2Blocks(data,prefix='v2b'){return (data?.blocks||[]).map((b,i)=>{let text=E(b.text||'');if(b.type==='table'){return `<div class="story-block" id="${prefix}${i}"><table class="story-table">${(b.rows||[]).map(r=>`<tr>${r.map(c=>`<td>${E(c)}</td>`).join('')}</tr>`).join('')}</table></div>`}let tag=/Heading 1/i.test(b.style)?'h1':/Heading 2/i.test(b.style)?'h2':/Heading 3/i.test(b.style)?'h3':/Heading 4/i.test(b.style)?'h4':'p';let rich=(b.runs||[]).map(x=>`${x.bold?'<strong>':''}${x.italic?'<em>':''}${E(x.text)}${x.italic?'</em>':''}${x.bold?'</strong>':''}`).join('')||text;return `<div class="story-block" id="${prefix}${i}"><${tag}>${rich}</${tag}></div>`}).join('')}
function adventureData(a){return a.id==='a5'?story:v2content.adventures?.[a.source]||a.content}
function adventureState(a){return state.v2.adventureState[a.id]||(state.v2.adventureState[a.id]={notes:'',favorites:[],favorite:false,lastSection:0,lastOpened:null})}
function adventuresView(){let list=(state.v2.adventures||[]).filter(a=>!a.archived);return `<div class="library-view"><section class="panel library-head"><div><h1 class="page-heading">Biblioteca de Aventuras</h1><p>Cinco fontes da campanha, com estado de leitura e notas separados por aventura.</p></div><div><button class="metal-btn" id="import-adventure">＋ Importar aventura</button><button class="metal-btn" id="add-adventure">＋ Cadastro manual</button><input hidden id="adventure-file" type="file" accept=".docx,.txt,.md,text/plain,text/markdown,application/vnd.openxmlformats-officedocument.wordprocessingml.document"></div></section><section class="adventure-grid">${list.map(a=>{let s=adventureState(a),data=adventureData(a);return `<article class="panel adventure-card"><small>Aventura ${a.number||'—'} · ${E(a.category||'Importada')}</small><h2>${s.favorite?'★ ':''}${E(a.title)}</h2><p>${E(a.description||'Sem descrição cadastrada.')}</p><p class="source-note">Fonte: ${E(a.source||'Cadastro local')} · ${data?.blocks?.length||0} blocos</p><label>Status <select data-adv-status="${E(a.id)}">${['Planejada','Em andamento','Concluída'].map(x=>`<option ${a.status===x?'selected':''}>${x}</option>`).join('')}</select></label><p class="source-note">${s.lastOpened?`Última abertura: ${new Date(s.lastOpened).toLocaleString('pt-BR')}`:'Ainda não aberta'}</p><div><button class="metal-btn" data-open-adventure="${E(a.id)}">Abrir</button><button class="metal-btn" data-favorite-adventure="${E(a.id)}">${s.favorite?'★ Favorita':'☆ Favoritar'}</button>${a.protected?' <span class="protected">Conteúdo aprovado</span>':` <button class="metal-btn danger-btn" data-delete-adventure="${E(a.id)}">Arquivar</button>`}</div></article>`}).join('')}</section></div>`}
function v2ReaderView(){let reader=state.v2.ui.reader||{},a=(state.v2.adventures||[]).find(x=>x.id===reader.adventureId);if(!a)return adventuresView();let data=adventureData(a),headings=data?.headings||[],s=adventureState(a);return `<div class="story-layout v2-reader-layout"><aside class="story-side panel"><h2>${E(a.title)}</h2><button class="metal-btn" data-view="adventures">← Aventuras</button><h3>Índice</h3>${headings.map(x=>`<button class="story-link l${Math.min(x.level,3)}" data-v2jump="${x.blockIndex}">${E(x.label)}</button>`).join('')||'<p class="source-note">O original não contém estilos de título. Use a busca.</p>'}</aside><article class="story-reader panel"><header class="reader-head"><input class="reader-search" id="v2-reader-search" placeholder="Buscar nesta aventura…"><h1>${E(a.title)}</h1><p>${E(a.category)} · Fonte preservada: ${E(a.source||'local')}</p></header><div class="story-scroll" id="v2-story-scroll"><div class="parchment-page">${v2Blocks(data,'v2b')}</div><section class="master-notes"><h3>Notas exclusivas do mestre</h3><textarea id="adventure-notes" rows="7" placeholder="Essas notas não alteram o original e não aparecem na galeria.">${E(s.notes||'')}</textarea></section></div></article></div>`}
function lofiView(){let items=state.v2.lofi||[];return `<div class="library-view"><section class="panel library-head"><div><h1 class="page-heading">Biblioteca LOFI</h1><p>Links locais do YouTube. O aplicativo não incorpora player nem acessa a internet automaticamente.</p></div><button class="metal-btn" id="add-lofi">＋ Adicionar LOFI</button></section><section class="panel lofi-form hidden" id="lofi-form"><h2 id="lofi-form-title">Novo link</h2><input id="lofi-id" type="hidden"><label>Título <input id="lofi-title" maxlength="120"></label><label>URL YouTube <input id="lofi-url" type="url" placeholder="Cole uma URL HTTPS de youtube.com ou youtu.be"></label><label>Categoria / ambiente <input id="lofi-category" maxlength="80" placeholder="Floresta, taverna, batalha…"></label><label>Observações <textarea id="lofi-notes" rows="3"></textarea></label><button class="metal-btn" id="save-lofi">Salvar link</button> <button class="metal-btn" id="cancel-lofi">Cancelar</button></section><section class="panel library-list"><label class="library-search">Buscar <input id="lofi-search" placeholder="Título, categoria ou observação"></label><div id="lofi-list">${lofiRows(items)}</div></section></div>`}
function lofiRows(items){return items.length?items.map(x=>`<article class="lofi-row"><div><h2>${E(x.title)}</h2><p>${E(x.category||'Sem categoria')} · ${E(x.notes||'Sem observações')}</p><small>${E(x.url)}</small></div><div><button class="metal-btn" data-open-lofi="${E(x.id)}">Abrir</button><button class="metal-btn" data-edit-lofi="${E(x.id)}">Editar</button><button class="metal-btn danger-btn" data-delete-lofi="${E(x.id)}">Excluir</button></div></article>`).join(''):'<p class="empty-state">Nenhum link LOFI cadastrado.</p>'}
function mapsView(){let base=[['middle-earth-large','Terra-média — mapa geral','Geral','RPG_Master_V2_Content_Handoff/originais/atlas/big-middle-earth-map.jpg'],['middle-earth-50','Terra-média — mapa 50','Geral','RPG_Master_V2_Content_Handoff/originais/atlas/map-middle-earth-50.jpg'],['middle-earth-b','Terra-média — mapa B','Geral','RPG_Master_V2_Content_Handoff/originais/atlas/map-middle-earth-b.jpg'],['mordor','Mordor','Regiões','RPG_Master_V2_Content_Handoff/originais/atlas/mordor-map.jpg']].map(x=>({id:x[0],title:x[1],category:x[2],url:x[3]}));let all=[...base,...(state.v2.importedMaps||[])];return `<div class="library-view"><section class="panel library-head"><div><h1 class="page-heading">Atlas da Campanha</h1><p>Mapas originais locais, sem recorte ou substituição. Use o visualizador para zoom e arrastar.</p></div><div><button class="metal-btn" id="import-map">＋ Anexar mapa</button><button class="metal-btn" id="open-cities-reader">Cidades LOTR — buscar</button><button class="metal-btn" id="open-cities-pdf">Abrir PDF original</button><input hidden id="map-file" type="file" accept="image/png,image/jpeg,image/webp"></div></section><section class="panel"><label class="library-search">Buscar mapas <input id="map-search" placeholder="Nome ou categoria"></label><div class="map-grid" id="map-list">${mapCards(all)}</div></section></div>`}
function mapCards(items){return items.map(m=>`<button class="map-card" data-open-map="${E(m.id)}"><img src="${E(m.url)}" alt="${E(m.title)}"><span>${E(m.title)}</span><small>${E(m.category||'Mapa')}</small></button>`).join('')}
function rulesView(){let ruleDocs=[['d20','D20 Simplificado.docx','D20 Simplificado','Referência principal da campanha'],['summary','Resumo Técnico.docx','Resumo Técnico','Consulta rápida complementar']];return sourceLibrary('Compêndio de Regras','D20 Simplificado é a referência principal. Nenhuma regra externa foi inserida.',ruleDocs,'rules')}
function documentsView(){let docs=[['letter-nando','Carta Nando Serenata.docx','Carta para Nando Serenata','Carta de Alatar'],['letter-elenya','Carta Elenya.docx','Carta para Elenya','Carta de Alatar'],['letter-calion','Carta Calion.docx','Carta para Calion','Carta de Alatar'],['lute','Item Lendário - Alaúde de Húrinel, O Eco da Esperança(1).docx','Alaúde de Húrinel, O Eco da Esperança','Item lendário']];return sourceLibrary('Documentos Narrativos','Privados por padrão: estes documentos não são exibidos pela Galeria.',docs,'documents')}
function sourceLibrary(title,description,items,kind){return `<div class="library-view"><section class="panel library-head"><div><h1 class="page-heading">${title}</h1><p>${description}</p></div></section><section class="panel library-list"><label class="library-search">Buscar <input id="source-search" placeholder="Buscar em títulos e textos"></label><div id="source-list">${sourceRows(items,kind)}</div></section></div>`}
function sourceRows(items,kind){return items.map(x=>{let data=v2content[kind]?.[x[1]],body=(data?.blocks||[]).map(b=>b.text||'').join(' ');return `<article class="source-row" data-source-search="${E((x[2]+' '+x[3]+' '+body).toLowerCase())}"><div><small>${E(x[3])}</small><h2>${E(x[2])}</h2><p>Fonte preservada: ${E(x[1])} · ${data?.blocks?.length||0} blocos</p></div><button class="metal-btn" data-open-source="${E(kind)}|${E(x[1])}|${E(x[2])}">Ler</button></article>`}).join('')}
function openSourceReader(kind,key,title){state.v2.ui.reader={kind,key,title};state.app.view='source-reader';persist();render()}
function sourceReaderView(){let r=state.v2.ui.reader||{},data=r.kind==='atlasCities'?v2content.atlasCities:v2content[r.kind]?.[r.key];if(!data)return `<div class="panel library-view"><p>Documento não encontrado.</p></div>`;let headings=data.headings||[];let back=r.kind==='rules'?'rules':r.kind==='atlasCities'?'maps':'documents';return `<div class="story-layout v2-reader-layout"><aside class="story-side panel"><button class="metal-btn" data-view="${back}">← Voltar</button><h2>${E(r.title)}</h2>${headings.map(x=>`<button class="story-link l${Math.min(x.level,3)}" data-v2jump="${x.blockIndex}">${E(x.label)}</button>`).join('')}</aside><article class="story-reader panel"><header class="reader-head"><input class="reader-search" id="v2-reader-search" placeholder="Buscar no documento…"><h1>${E(r.title)}</h1><p>Fonte: ${E(data.source)}</p></header><div class="story-scroll"><div class="parchment-page document-parchment">${v2Blocks(data,'v2b')}</div></div></article></div>`}
function players(){return `<div class="players"><h1 class="page-heading">Selecione um Jogador</h1><div class="card-grid">${Object.values(state.characters).map(c=>`<article class="char-card panel ${c.id==='anao'?'dwarf-card':''}" ${c.id==='anao'?'data-idle="anao"':''}>${c.id==='anao'?dwarfActor():`<div class="sprite sprite-${c.id}" role="img" aria-label="Animação em pixel art de ${E(c.name)}"></div>`}<h2>${E(c.name)}</h2><p>${E(c.info.race)} · ${E(c.info.classLevel)}</p><button class="metal-btn" data-char="${c.id}">Ver ficha</button></article>`).join('')}</div></div>`}
function character(){let c=state.characters[state.app.char],tab=state.app.tab, combat=+c.combat.hpCurrent<+c.combat.hpMax/2;let stats=tab==='Atributos'||tab==='Visão Geral'?attributes(c):`<div class="section-content"><h3>Dados de sessão</h3><p>Proficiência: ${E(c.combat.proficiency)}<br>Renome: ${E(c.info.renown)}<br>Inspiração: ${E(c.combat.inspiration)}</p>${combat?'<p style="color:#ffb08e">● EM COMBATE — PV abaixo da metade</p>':''}</div>`;return `<div class="sheet"><aside class="sheet-side panel">${['Visão Geral','Atributos','Perícias','Poderes / Runas / Magias','Equipamentos','Inventário','Background','Anotações'].map(t=>`<button class="sheet-tab ${tab===t?'active':''}" data-tab="${t}">${t}</button>`).join('')}</aside><section class="sheet-main panel"><h1 class="char-name">${E(c.name)}</h1><p class="char-sub">${E(c.info.race)} · ${E(c.info.classLevel)} · fonte: ${E(c.sourceFile)}</p>${mainTab(c,tab,combat)}</section><aside class="sheet-stats panel"><div class="kpis">${kpi('PV',c.combat.hpCurrent,'hpCurrent',c)}${kpi('PV Máx.',c.combat.hpMax,'hpMax',c)}${kpi('CA',c.combat.ac,'ac',c)}${kpi('Iniciativa',c.combat.initiative,'initiative',c)}${kpi('Deslocamento',c.combat.movement,'movement',c)}</div>${stats}</aside></div>`}
function kpi(label,val,key,c){return `<div class="kpi"><label>${label}</label><input data-field="combat.${key}" value="${E(val)}" aria-label="${label} de ${E(c.name)}">${key==='hpCurrent'?`<div class="hpbar"><i style="width:${hp(c)}%"></i></div>`:''}</div>`}function hp(c){let a=+c.combat.hpCurrent,b=+c.combat.hpMax;return Number.isFinite(a)&&Number.isFinite(b)&&b>0?Math.max(0,Math.min(100,a/b*100)):0}
function attributes(c){return `<table class="attr-table"><thead><tr><td>Atributo</td><td>Valor</td><td>Mod.</td><td>Salv.</td></tr></thead><tbody>${c.attributes.map((a,i)=>`<tr><td>${E(a.name)}</td><td><input data-attr="${i}.value" value="${E(a.value)}"></td><td><input data-attr="${i}.modifier" value="${E(a.modifier)}"></td><td><input data-attr="${i}.save" value="${E(a.save)}"></td></tr>`).join('')}</tbody></table>`}
function mainTab(c,t,combat){if(t==='Visão Geral')return `<div class="portrait-wrap ${combat?'combat':''}" data-idle="${c.id}">${c.id==='anao'?dwarfActor():`<div class="sprite sprite-${c.id}" role="img" aria-label="Animação em pixel art de ${E(c.name)}"></div>`}</div><div class="section-content"><h3>${E(c.info.background)}</h3><p>${E(c.background[0]||'Não informado na ficha')}</p></div>`;if(t==='Atributos')return `<div class="section-content"><h3>Atributos editáveis</h3>${attributes(c)}</div>`;if(t==='Perícias')return listEdit('skills',c.skills,c);if(t==='Poderes / Runas / Magias')return listEdit('powers',c.powers,c);if(t==='Equipamentos'||t==='Inventário')return listEdit('inventory',c.inventory,c);if(t==='Background')return `<div class="section-content"><h3>Background</h3><p class="char-sub">${c.id==='nando'?'Histórico conforme planilha original.':''}</p><textarea class="note-box" rows="17" data-background>${E(c.background.join('\n\n'))}</textarea></div>`;return `<div class="section-content"><h3>Anotações do mestre</h3><textarea class="note-box" rows="12" data-notes>${E(c.notes.join('\n'))}</textarea><p>${c.sourceDiscrepancies.length?'Divergências preservadas na documentação.':''}</p></div>`}
function listEdit(key,items,c){let title=key==='skills'?'Perícias':key==='powers'?'Poderes / Runas / Magias':'Equipamentos e inventário';return `<div class="section-content"><h3>${title}</h3><ul class="editable-list">${items.map((r,i)=>`<li><input data-list="${key}.${i}" value="${E(r.join(' — '))}"><button class="metal-btn" data-remove="${key}.${i}">×</button></li>`).join('')}</ul><div class="add-row"><input id="add-value" placeholder="Novo item"><button class="metal-btn" data-add="${key}">Adicionar</button></div></div>`}
function diceHistoryMarkup(){let h=state.diceHistory||[];return h.length?h.map(x=>`<li><b>${E(x.notation||`d${x.die}`)}</b> ${x.roll}${x.bonus>=0?'+':''}${x.bonus} = <strong>${x.total}</strong></li>`).join(''):'<li class="dice-empty">Nenhuma rolagem nesta sessão.</li>'}
function diceView(){
  let die=Number(state.app.diceType||20),bonus=Number(state.app.diceBonus||0),quantity=Math.max(1,Math.min(12,Number(state.app.diceQuantity||1))),formula=state.app.diceFormula||'';
  return `<div class="dice-layout dice-layout-3d"><section class="dice-board panel"><header class="dice-controlbar"><div><h1 class="page-heading">Mesa de Dados</h1><p>Física 3D local · selecione o dado e lance-o na mesa.</p></div><div class="dice-choices" aria-label="Tipo de dado">${[4,6,8,10,12,20,100].map(n=>`<button class="die-choice ${die===n?'active':''}" data-die="${n}">d${n}</button>`).join('')}</div><label class="dice-quantity">Qtd. <input id="dice-quantity" type="number" min="1" max="12" value="${quantity}" step="1" inputmode="numeric"></label><label class="dice-bonus">Bônus <input id="dice-bonus" type="number" value="${bonus}" step="1" inputmode="numeric"></label><button class="metal-btn dice-roll" id="roll-dice">⚄ Jogar dados</button><div class="dice-formula-row"><label>Combinação livre <input id="dice-formula" value="${E(formula)}" placeholder="Ex.: 1d4 + 2d6 + 1d8" spellcheck="false"></label><span>Use + entre d4, d6, d8, d10, d12, d20 e d100.</span><button class="metal-btn dice-roll" id="roll-formula">⚄ Jogar combinação</button></div></header><div class="dice-table-frame"><div id="dice-3d-stage" class="dice-3d-stage" aria-label="Mesa tridimensional de lançamento"><div class="dice-loading">Preparando mesa física…</div></div></div><div class="dice-result" id="dice-result">A mesa está pronta para uma rolagem.</div></section><aside class="dice-history panel"><h2>Últimas rolagens</h2><ol id="dice-history">${diceHistoryMarkup()}</ol><button class="metal-btn" id="clear-dice-history">Limpar histórico</button></aside></div>`
}
async function bootDice3d(){let host=$('#dice-3d-stage');if(!host||host.dataset.diceReady==='true')return dice3d;if(dice3dBoot)return dice3dBoot;dice3dBoot=import('./dice3d.js').then(m=>m.mountDiceTable()).then(box=>{dice3d=box;$('#dice-3d-stage .dice-loading')?.remove();return box}).catch(error=>{console.error(error);host=$('#dice-3d-stage');if(host)host.innerHTML='<p class="dice-error">A mesa 3D não pôde ser inicializada. Abra pelo INICIAR_RPG para usar os recursos físicos locais.</p>';return null}).finally(()=>{dice3dBoot=null});return dice3dBoot}
function parseDiceFormula(raw){let compact=String(raw||'').toLowerCase().replace(/\s+/g,''),token=/(\d*)d(100|20|12|10|8|6|4)/g,items=[],cursor=0,match;while((match=token.exec(compact))){if(match.index!==cursor)return null;let count=Number(match[1]||1),sides=Number(match[2]);if(!Number.isInteger(count)||count<1||count>12)return null;items.push({count,sides});cursor=token.lastIndex;if(compact[cursor]==='+')cursor++}if(!items.length||cursor!==compact.length)return null;let physical=items.reduce((sum,x)=>sum+x.count*(x.sides===100?2:1),0);return physical<=24?items:null}
function currentDiceRequest(useFormula=false){let formula=String($('#dice-formula')?.value||state.app.diceFormula||'').trim(),items=useFormula?parseDiceFormula(formula):[{sides:Number(state.app.diceType||20),count:Math.max(1,Math.min(12,Number(state.app.diceQuantity||1)))}];return items?{items,notation:items.map(x=>`${x.count}d${x.sides}`).join(' + ')}:null}
function physicalResult(items,results){let rolls=Array.isArray(results)?results:[results],at=0,faces=[];items.forEach(item=>{for(let i=0;i<item.count;i++){if(item.sides===100){let tens=Number(rolls[at++]?.value??0),units=Number(rolls[at++]?.value??0)%10,value=tens+units;if(value===0)value=100;faces.push({label:'d100',value,detail:`${String(tens).padStart(2,'0')}+${units}`})}else faces.push({label:`d${item.sides}`,value:Number(rolls[at++]?.value??1)})}});let roll=faces.reduce((sum,x)=>sum+x.value,0),detail=faces.map(x=>`${x.label}: ${x.detail||x.value}`).join(' · ');return {roll,detail}}
async function rollDice(useFormula=false){if(diceRolling)return;let request=currentDiceRequest(useFormula),bonus=Number(state.app.diceBonus||0),result=$('#dice-result'),buttons=[$('#roll-dice'),$('#roll-formula')];if(!request){result&&(result.textContent='Combinação inválida. Exemplo válido: 1d4 + 2d6 + 1d8.');return}diceRolling=true;buttons.forEach(button=>button&&(button.disabled=true));result&&(result.textContent='Os dados foram lançados…');try{let box=await bootDice3d();if(!box)throw Error('Mesa indisponível');let outcome=physicalResult(request.items,await import('./dice3d.js').then(m=>m.throwPhysicalDice(request.items))),total=outcome.roll+bonus;result.innerHTML=`<b>Dados: ${E(request.notation)}</b><span>${E(outcome.detail)}</span><span>Bônus: ${bonus>=0?'+':''}${bonus}</span><strong>Resultado final: ${total}</strong>`;state.diceHistory=state.diceHistory||[];state.diceHistory.unshift({notation:request.notation,die:request.items[0].sides,roll:outcome.roll,bonus,total,at:Date.now()});state.diceHistory=state.diceHistory.slice(0,8);$('#dice-history').innerHTML=diceHistoryMarkup();persist()}catch(error){console.error(error);if(result)result.textContent='Não foi possível concluir esta rolagem física.'}finally{diceRolling=false;buttons.forEach(button=>button&&(button.disabled=false))}}
function bindDice(){document.querySelectorAll('[data-die]').forEach(b=>b.onclick=()=>{state.app.diceType=Number(b.dataset.die);persist();render()});let bonus=$('#dice-bonus'),quantity=$('#dice-quantity'),formula=$('#dice-formula'),saveBonus=e=>{state.app.diceBonus=Number(e.target.value)||0;persist()},saveQuantity=e=>{state.app.diceQuantity=Math.max(1,Math.min(12,Number(e.target.value)||1));persist()},saveFormula=e=>{state.app.diceFormula=e.target.value;persist()};bonus?.addEventListener('input',saveBonus);bonus?.addEventListener('change',saveBonus);quantity?.addEventListener('input',saveQuantity);quantity?.addEventListener('change',saveQuantity);formula?.addEventListener('input',saveFormula);formula?.addEventListener('change',saveFormula);formula?.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();rollDice(true)}});$('#roll-dice')?.addEventListener('click',()=>rollDice(false));$('#roll-formula')?.addEventListener('click',()=>rollDice(true));$('#clear-dice-history')?.addEventListener('click',()=>{state.diceHistory=[];persist();render()})}
function visualEntries(){let custom=state.v2.visualLibrary||[],ids=new Set(codexContent.visualEntries.map(x=>x.id)),overrides=new Map(custom.map(x=>[x.id,x]));return [...codexContent.visualEntries.map(x=>overrides.get(x.id)||x).filter(x=>!x.archived),...custom.filter(x=>!ids.has(x.id)&&!x.archived)]}
function galleryView(){let filters=['Todas','NPC','Aliado','Inimigo','Criatura','Entidade','Lenda'],ui=state.v2.ui.visual||{},all=visualEntries(),q=(ui.q||'').toLowerCase(),visible=all.filter(x=>(!ui.category||ui.category==='Todas'||x.category===ui.category)&&(!ui.origin||x.origin===ui.origin)&&(!q||[x.name,x.description,x.tags?.join(' '),x.origin].join(' ').toLowerCase().includes(q))).sort((a,b)=>(ui.sort==='Origem'?a.origin.localeCompare(b.origin):a.name.localeCompare(b.name)));let origins=[...new Set(all.map(x=>x.origin))].sort();return `<div class="library-view codex-view"><section class="panel library-head"><div><h1 class="page-heading">Biblioteca Visual</h1><p>NPCs, aliados, inimigos, criaturas, entidades e lendas da campanha.</p></div><button class="metal-btn" data-add-visual>＋ Adicionar item</button></section><section class="panel codex-tools"><input id="visual-search" placeholder="Buscar nome, origem ou tag" value="${E(ui.q||'')}"><select id="visual-category"><option>Todas</option>${filters.slice(1).map(x=>`<option ${ui.category===x?'selected':''}>${x}</option>`).join('')}</select><select id="visual-origin"><option value="">Todas as origens</option>${origins.map(x=>`<option ${ui.origin===x?'selected':''}>${E(x)}</option>`).join('')}</select><select id="visual-sort"><option ${ui.sort!=='Origem'?'selected':''}>Nome</option><option ${ui.sort==='Origem'?'selected':''}>Origem</option></select></section><section class="codex-grid">${visible.map(x=>`<article class="panel codex-card"><img src="${E(x.image)}" alt="${E(x.name)}"><div><small>${E(x.category)} · ${E(x.origin)}</small><h2>${E(x.name)}</h2><p>${E(x.description)}</p><span class="status-chip">${E(x.status)}</span><div><button class="metal-btn" data-detail-visual="${E(x.id)}">Detalhe</button>${state.v2.visualLibrary?.some(y=>y.id===x.id)?` <button class="metal-btn" data-edit-visual="${E(x.id)}">Editar</button>`:''}</div></div></article>`).join('')||'<p class="empty-state">Nenhuma entrada encontrada.</p>'}</section></div>`}
function creaturesList(){let custom=state.v2.creatures||[],ids=new Set(codexContent.creatures.map(x=>x.id)),overrides=new Map(custom.map(x=>[x.id,x]));return [...codexContent.creatures.map(x=>overrides.get(x.id)||x).filter(x=>!x.archived),...custom.filter(x=>!ids.has(x.id)&&!x.archived)]}
function creaturesView(){let ui=state.v2.ui.creatures||{},q=(ui.q||'').toLowerCase(),types=[...new Set(creaturesList().map(x=>x.type))],list=creaturesList().filter(x=>(!ui.type||x.type===ui.type)&&(!q||[x.name,x.type,x.origin,x.tags?.join(' ')].join(' ').toLowerCase().includes(q)));return `<div class="library-view codex-view"><section class="panel library-head"><div><h1 class="page-heading">Criaturas</h1><p>Bestiário rápido para o mestre. Fichas resumidas seguem o D20 Simplificado.</p></div><button class="metal-btn" data-add-creature>＋ Adicionar criatura</button></section><section class="panel codex-tools"><input id="creature-search" placeholder="Buscar criatura, tipo ou origem" value="${E(ui.q||'')}"><select id="creature-type"><option value="">Todos os tipos</option>${types.map(x=>`<option ${ui.type===x?'selected':''}>${E(x)}</option>`).join('')}</select></section><section class="codex-grid creature-grid">${list.map(x=>`<article class="panel codex-card"><img src="${E(x.image)}" alt="${E(x.name)}"><div><small>${E(x.type)} · ${E(x.origin)}</small><h2>${E(x.name)}</h2><p>${E(x.description)}</p><div><button class="metal-btn" data-detail-creature="${E(x.id)}">Ficha rápida</button>${state.v2.creatures?.some(y=>y.id===x.id)?` <button class="metal-btn" data-edit-creature="${E(x.id)}">Editar</button>`:''}</div></div></article>`).join('')||'<p class="empty-state">Nenhuma criatura encontrada.</p>'}</section></div>`}
