function settings(){return `<div class="settings"><section class="panel"><h2>Configurações locais</h2><p>Os dados ficam somente neste navegador/dispositivo. Nenhuma conexão externa é usada.</p><button class="metal-btn" id="sound">Som: ${state.app.sound?'ligado':'desligado'}</button></section><section class="panel"><h2>Backup e restauração</h2><p>Exporte fichas, configurações, imagens importadas, biblioteca de aventuras, progresso de leitura, notas do mestre, LOFI e mapas anexados em um JSON versionado. A restauração valida o arquivo antes de substituir os dados atuais.</p><button class="metal-btn" id="export">⇩ Exportar backup</button> <button class="metal-btn" id="import">⇧ Importar backup</button><input hidden id="backup-file" type="file" accept="application/json,.json"></section><section class="panel"><h2>Ajuda</h2><p>História 5, Jogadores, Dados, Imagens e Configurações continuam disponíveis. Aventuras, Mapas, Regras, LOFI e Documentos usam fontes locais; os documentos narrativos não entram na Galeria de apresentação.</p><button class="metal-btn" id="print">Imprimir ficha</button></section><section class="panel"><h2>Fonte dos dados</h2><p>Fontes V1 preservadas e pacote RPG Master V2 Content Handoff. As regras da campanha seguem D20 Simplificado.docx; divergências narrativas permanecem nos originais.</p></section></div>`}
function bind(){document.querySelectorAll('[data-view]').forEach(x=>x.onclick=()=>{state.app.view=x.dataset.view;persist();render()});$('#players-menu')?.addEventListener('click',e=>{e.stopPropagation();$('#dropdown').classList.toggle('open')});$('#library-menu')?.addEventListener('click',e=>{e.stopPropagation();$('#library-dropdown').classList.toggle('open')});document.addEventListener('click',()=>{$('#dropdown')?.classList.remove('open');$('#library-dropdown')?.classList.remove('open')},{once:true});document.querySelectorAll('[data-char]').forEach(x=>x.onclick=()=>{state.app.char=x.dataset.char;state.app.view='character';persist();render()});document.querySelectorAll('[data-tab]').forEach(x=>x.onclick=()=>{state.app.tab=x.dataset.tab;persist();render()});document.querySelectorAll('[data-jump]').forEach(x=>x.onclick=()=>{let target=$('#'+x.dataset.jump);target?.scrollIntoView({block:'start'});state.app.lastSection=x.dataset.jump;persist()});$('#reader-search')?.addEventListener('input',e=>{let q=e.target.value.toLowerCase();document.querySelectorAll('.story-block').forEach(n=>n.classList.toggle('hidden',q&&!n.textContent.toLowerCase().includes(q)))});document.querySelectorAll('[data-field]').forEach(x=>x.onchange=()=>{setPath(state.characters[state.app.char],x.dataset.field,x.value);persist();render()});document.querySelectorAll('[data-attr]').forEach(x=>x.onchange=()=>{let [i,k]=x.dataset.attr.split('.');state.characters[state.app.char].attributes[i][k]=x.value;persist()});document.querySelectorAll('[data-list]').forEach(x=>x.onchange=()=>{let [k,i]=x.dataset.list.split('.');state.characters[state.app.char][k][i]=x.value.split(' — ');persist()});$('[data-background]')?.addEventListener('change',e=>{state.characters[state.app.char].background=e.target.value.split(/\n\n+/);persist()});$('[data-notes]')?.addEventListener('change',e=>{state.characters[state.app.char].notes=e.target.value.split('\n').filter(Boolean);persist()});document.querySelectorAll('[data-remove]').forEach(x=>x.onclick=()=>{let [k,i]=x.dataset.remove.split('.');state.characters[state.app.char][k].splice(i,1);persist();render()});document.querySelectorAll('[data-add]').forEach(x=>x.onclick=()=>{let v=$('#add-value').value.trim();if(v){state.characters[state.app.char][x.dataset.add].push([v]);persist();render()}});$('[data-idle]')?.addEventListener('click',()=>{if(state.app.sound)beep();let p=$('.portrait-wrap');p.animate([{transform:'translateX(-4px)'},{transform:'translateX(4px)'},{transform:'none'}],{duration:450})});document.querySelectorAll('[data-cat]').forEach(x=>x.onclick=()=>{activeGallery=x.dataset.cat;render()});$('#import-image')?.addEventListener('click',()=>$('#image-import').click());document.querySelectorAll('[data-image]').forEach(x=>x.onclick=()=>openImage(x.dataset.image));$('#sound')?.addEventListener('click',()=>{state.app.sound=!state.app.sound;persist();render()});$('#export')?.addEventListener('click',exportBackup);$('#import')?.addEventListener('click',()=>$('#backup-file').click());$('#backup-file')?.addEventListener('change',importBackup);$('#print')?.addEventListener('click',()=>window.print());bindV2();bindCodex()}
