function ask(label,value=''){return prompt(label,value)}
function addVisual(){let name=ask('Nome do item visual:');if(!name?.trim())return;let category=ask('Categoria (NPC, Aliado, Inimigo, Criatura, Entidade ou Lenda):','NPC')||'NPC',origin=ask('Origem narrativa:','Outro')||'Outro',description=ask('Descrição curta:','Entrada manual da campanha.')||'',notes=ask('Notas do mestre:','')||'',tags=(ask('Tags separadas por vírgula:','manual')||'').split(',').map(x=>x.trim()).filter(Boolean),id='visual-'+crypto.randomUUID();state.v2.visualLibrary.push({id,name:name.trim(),category,origin,image:'assets/fangorn_atmosphere_crop.jpg',description,notes,tags,status:'futuro'});persist();render();toast('Item visual adicionado. Use Editar para ajustar ou substituir a imagem.')}
function editVisual(id){let x=state.v2.visualLibrary.find(y=>y.id===id);if(!x){let base=codexContent.visualEntries.find(y=>y.id===id);if(!base)return;x={...base,tags:[...(base.tags||[])]};state.v2.visualLibrary.push(x)}x.name=ask('Nome:',x.name)||x.name;x.category=ask('Categoria:',x.category)||x.category;x.origin=ask('Origem:',x.origin)||x.origin;x.description=ask('Descrição:',x.description)||x.description;x.notes=ask('Notas do mestre:',x.notes)||x.notes;x.status=ask('Status narrativo:',x.status)||x.status;let action=ask('Digite I para substituir imagem, E para excluir, ou Enter para salvar:','');if(action?.toUpperCase()==='E'){if(confirm(`Excluir “${x.name}”?`)){x.archived=true}}else if(action?.toUpperCase()==='I'){state.v2.ui.visualTarget=id;$('#image-import').click();return}persist();render()}
function addCreature(){let name=ask('Nome da criatura:');if(!name?.trim())return;let type=ask('Tipo:','Criatura'),origin=ask('Origem narrativa:','Outro'),ac=Number(ask('CA:','12'))||12,hp=Number(ask('PV:','18'))||18,id='creature-'+crypto.randomUUID();state.v2.creatures.push({id,name:name.trim(),type,origin,image:'assets/generated/creatures/vigia-de-hrim.png',description:ask('Descrição curta:','Criatura adicionada manualmente.')||'',ac,hp,movement:ask('Movimento:','9 m')||'9 m',attributes:{for:10,des:10,con:10,int:8,sab:10,car:8},attack:ask('Ataque principal:','Ataque +3')||'Ataque +3',damage:ask('Dano:','1d6+1')||'1d6+1',special:ask('Habilidade especial:','—')||'—',note:ask('Observação do mestre:','')||'',tags:['manual']});persist();render();toast('Criatura adicionada ao bestiário.')}
function editCreature(id){let x=state.v2.creatures.find(y=>y.id===id);if(!x){let base=codexContent.creatures.find(y=>y.id===id);if(!base)return;x={...base,attributes:{...base.attributes},tags:[...(base.tags||[])]};state.v2.creatures.push(x)}x.name=ask('Nome:',x.name)||x.name;x.type=ask('Tipo:',x.type)||x.type;x.origin=ask('Origem:',x.origin)||x.origin;x.description=ask('Descrição:',x.description)||x.description;x.ac=Number(ask('CA:',x.ac))||x.ac;x.hp=Number(ask('PV:',x.hp))||x.hp;x.attack=ask('Ataque:',x.attack)||x.attack;x.damage=ask('Dano:',x.damage)||x.damage;x.special=ask('Especial:',x.special)||x.special;if(confirm(`Deseja excluir “${x.name}”? Escolha Cancelar para salvar as alterações.`)){x.archived=true}persist();render()}
function validYouTube(url){try{let u=new URL(url),host=u.hostname.toLowerCase();return u.protocol==='https:'&&['youtube.com','www.youtube.com','music.youtube.com','youtu.be'].includes(host)}catch(_){return false}}
