function saveLofi(){let id=$('#lofi-id').value||crypto.randomUUID(),title=$('#lofi-title').value.trim(),url=$('#lofi-url').value.trim(),category=$('#lofi-category').value.trim(),notes=$('#lofi-notes').value.trim();if(!title||!validYouTube(url)){toast('Informe um título e uma URL HTTPS válida do YouTube.');return}let at=state.v2.lofi.findIndex(x=>x.id===id),prior=state.v2.lofi[at],item={id,title,url,category,notes,order:prior?.order??state.v2.lofi.length,updatedAt:Date.now()};if(at>=0)state.v2.lofi[at]=item;else state.v2.lofi.push(item);persist();render();toast('Biblioteca LOFI salva localmente.')}
