function manualAdventure(){let title=prompt('Título da aventura:');if(!title?.trim())return;let text=prompt('Texto inicial (pode ser editado depois nas notas do mestre):')||'';let id='manual-'+crypto.randomUUID();state.v2.adventures.push({id,number:'+',title:title.trim(),category:'Cadastro manual',source:'Cadastro local',status:'Planejada',description:'Aventura cadastrada manualmente.',content:{source:'Cadastro local',blocks:text?[{type:'paragraph',text,style:'Normal',runs:[{text,bold:false,italic:false}]}]:[],headings:[]},originHash:'manual-'+Date.now(),version:1});state.v2.adventureState[id]={notes:'',favorites:[],lastSection:0,lastOpened:null};persist();render()}
