function playCharacterSound(id){if(!state.app.sound)return;let C=window.AudioContext||window.webkitAudioContext;if(!C)return;let a=new C(),at=a.currentTime,master=a.createGain(),compress=a.createDynamicsCompressor();master.gain.value=.62;compress.threshold.value=-16;compress.knee.value=12;compress.ratio.value=8;master.connect(compress).connect(a.destination);let tone=(freq,start,duration,type='sine',gain=.1,endFreq)=>{let o=a.createOscillator(),g=a.createGain();o.type=type;o.frequency.setValueAtTime(freq,at+start);if(endFreq)o.frequency.exponentialRampToValueAtTime(endFreq,at+start+duration);g.gain.setValueAtTime(gain,at+start);g.gain.exponentialRampToValueAtTime(.001,at+start+duration);o.connect(g).connect(master);o.start(at+start);o.stop(at+start+duration)},noise=(start,duration,gain,filterFreq)=>{let b=a.createBuffer(1,Math.ceil(a.sampleRate*duration),a.sampleRate),d=b.getChannelData(0);for(let i=0;i<d.length;i++)d[i]=(Math.random()*2-1)*(1-i/d.length);let src=a.createBufferSource(),f=a.createBiquadFilter(),g=a.createGain();f.type='bandpass';f.frequency.value=filterFreq;g.gain.setValueAtTime(gain,at+start);g.gain.exponentialRampToValueAtTime(.001,at+start+duration);src.buffer=b;src.connect(f).connect(g).connect(master);src.start(at+start)};if(id==='anao'){noise(0,.13,.55,1800);tone(64,0,.24,'sine',.44,37);tone(156,.012,.17,'square',.22,94);tone(318,.018,.12,'triangle',.16,170)}else if(id==='nando'){[392,494,587,740].forEach((n,i)=>tone(n,i*.035,.58,'triangle',.17,n*.72));tone(196,.02,.62,'sine',.12,160)}else if(id==='calion'){noise(0,.11,.30,980);tone(67,0,.25,'triangle',.34,43);tone(440,.07,.52,'sine',.12,880);tone(880,.11,.42,'sine',.08,1320)}else{noise(0,.16,.36,3400);tone(1120,0,.14,'sawtooth',.12,460);tone(610,.045,.19,'triangle',.16,330)}setTimeout(()=>a.close(),1100)}
document.addEventListener('click',e=>{let p=e.target.closest?.('[data-idle]');if(!p||e.target.closest?.('[data-char]'))return;let id=p.dataset.idle||state.app.char,s=p.querySelector('.sprite'),actionMs=760;if(id==='anao')playDwarfAction(p.querySelector('[data-dwarf-frame]'));else{s?.classList.remove('action');void s?.offsetWidth;s?.classList.add('action');setTimeout(()=>s?.classList.remove('action'),actionMs);playCharacterSound(id)}if(id==='anao'){let now=Date.now();characterClicks.anao=characterClicks.anao.filter(t=>now-t<2000);characterClicks.anao.push(now);if(characterClicks.anao.length>=3){p.classList.add('berserk');setTimeout(()=>p.classList.remove('berserk'),2500);characterClicks.anao=[]}}});
async function imageImport(e){let target=state?.v2?.ui?.visualTarget;for(let f of e.target.files){if(!f.type.startsWith('image/')||!f.size){toast('Arquivo de imagem inválido.');continue}let data=await new Promise((resolve,reject)=>{let r=new FileReader;r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(f)});if(target){let x=state.v2.visualLibrary.find(y=>y.id===target);if(x){x.image=data;state.v2.ui.visualTarget=null;persist();render();toast('Imagem do item visual substituída e incluída no backup.')}continue}let item={id:crypto.randomUUID(),title:f.name.replace(/\.[^.]+$/,''),category:'Outros',createdAt:Date.now(),mimeType:f.type,blob:f};try{await saveGallery(item);item.url=URL.createObjectURL(f);gallery.push(item);toast('Imagem armazenada localmente.');render()}catch(_){toast('Não foi possível salvar a imagem: IndexedDB indisponível.')}}e.target.value=''}
function openImage(id){let item=gallery.find(x=>x.id===id);if(!item)item={id,url:document.querySelector(`[data-image="${id}"] img`).src,title:document.querySelector(`[data-image="${id}"] figcaption`).textContent};let url=item.url||(item.blob?URL.createObjectURL(item.blob):'');let m=document.createElement('div');m.className='modal';m.innerHTML=`<button class="metal-btn">Fechar ×</button><figure><img src="${url}" alt="${E(item.title)}"><figcaption>${E(item.title)}</figcaption></figure>`;document.body.append(m);let close=()=>m.remove();m.onclick=e=>{if(e.target===m||e.target.tagName==='BUTTON')close()};document.addEventListener('keydown',function esc(e){if(e.key==='Escape'){close();document.removeEventListener('keydown',esc)}})}
async function exportBackup(){let images=[];for(let x of gallery){let b=x.blob;let data=await new Promise(r=>{let fr=new FileReader;fr.onload=()=>r(fr.result);fr.readAsDataURL(b)});images.push({id:x.id,title:x.title,category:x.category,createdAt:x.createdAt,mimeType:x.mimeType,data})}let blob=new Blob([JSON.stringify({schemaVersion:3,exportedAt:new Date().toISOString(),state,images})],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='fangorn-backup-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Backup V3 exportado com biblioteca visual e criaturas.')}async function importBackup(e){let f=e.target.files[0];if(!f)return;try{let x=JSON.parse(await f.text());if(![1,2,3].includes(x.schemaVersion)||!x.state?.characters)throw Error();if(!confirm('Substituir os dados locais pelo backup selecionado?'))return;state=x.state;ensureV2();gallery=[];for(let im of x.images||[]){let blob=await (await fetch(im.data)).blob(),it={...im,blob,url:URL.createObjectURL(blob)};await saveGallery(it);gallery.push(it)}persist();render();toast('Backup restaurado sem migração destrutiva.')}catch(_){toast('Backup inválido; os dados atuais foram preservados.')}finally{e.target.value=''}}function toast(t){let d=document.createElement('div');d.className='toast';d.textContent=t;document.body.append(d);setTimeout(()=>d.remove(),3500)}
$('#image-import').addEventListener('change',imageImport);(async()=>{state=fresh();try{let old=localStorage.getItem('fangorn-rpg-state');if(old)state=JSON.parse(old)}catch(_){}await openDB();await loadDB();state.app=state.app||{};state.app.diceType??=20;state.app.diceBonus??=0;state.diceHistory??=[];ensureV2();Object.keys(portraits).forEach(id=>{if(state.characters[id])state.characters[id].portrait=portraits[id]});gallery.forEach(x=>{if(x.blob)x.url=URL.createObjectURL(x.blob)});preloadDwarfFrames();render()})();
